      "itemType": "equipment",
      "level": 2,
      "rarity": "common",
      "traits": [
        "magical"
      ],
      "description": "Each one of these statuettes is 1 inch in height, carved from a specific material and taking the shape of a particular animal or animals.\nActivate 2 command, Interact\nEffect You activate the statue by placing it on solid ground and then speaking its name, causing the statuette to transform into a living creature or creatures. In creature form, the figurine has the minion trait. It can understand your language and it obeys you to the best of its ability when you use an action to command it. The specifics of each creature, as well as the activation's frequency (if any), appear in its entry below.\nIf the figurine is slain while in animal form, it reverts to its statue shape and cannot be activated again until 1 week has passed. If the figurine is destroyed in statue form, it is shattered and its magic is lost.\nThis simple onyx statue transforms into a Guard Dog.\nThe dog has a +4 circumstance bonus to Survival checks to Track, and it has darkvision. When the dog senses a hidden creature with its scent, that creature is instead observed and concealed.\nThe onyx dog can be activated once per week and remains in its form for up to 6 hours.",
