      "description": "This liquid contains blood from a silver dragon. For 1 hour after you imbibe the concoction, you can unleash a silver dragon's breath weapon. The potency of the breath depends on the potion's type, based on the age of the dragon whose blood was used to make the potion.\nExhaling dragon breath uses a single action. You create a 15-foot cone of fire which deals 4d6 cold damage. All creatures in the area must attempt a check (reflex, dc:23, basic, name:Young Silver Dragon's Breath Potion, options:area-effect) save.\nAfter you use the breath weapon, you can't do so again for 1d4.",
