    "sourceHash": "sha256:92f84e2aee3489f7736055ef664d79c30be91e71d96c33bc97a4bbec88b5609a",
    "translatableHash": "sha256:add16addba2bccc3aec2caf85d8609afe62f202308842153f25b692f1e426a54",
    "data": {
      "schemaVersion": 1,
      "name": "Black Dragon's Breath Potion (Young)",
      "itemType": "consumable",
      "level": 7,
      "rarity": "common",
      "traits": [
        "acid",
        "consumable",
        "magical",
        "potion"
      ],
      "description": "This liquid contains blood from a black dragon. For 1 hour after you imbibe the concoction, you can unleash a black dragon's breath weapon. The potency of the breath depends on the potion's type, based on the age of the dragon whose blood was used to make the potion.\nExhaling dragon breath uses a single action. You create a 30-foot line of acid which deals 4d6 acid damage. All creatures in the area must attempt a check (reflex, dc:23, basic, name:Young Black Dragon's Breath Potion, options:area-effect) save.\nAfter you use the breath weapon, you can't do so again for 1d4.",
      "bulk": 0.1,
      "price": {
        "gp": 70
      },
      "usage": "held-in-one-hand",
      "category": "potion",
      "group": "consumable"
    }
