      "level": 9,
      "rarity": "uncommon",
      "traits": [
        "consumable",
        "illusion",
        "magical"
      ],
      "description": "Activate A Interact\nThis powder shimmers like a thousand tiny motes of light. Activating the dust by sprinkling it on yourself or a creature within reach casts a 4th-rank Invisibility spell with a duration of 1 minute on that creature. This invisibility can't be negated or seen through by any spell of 3rd rank or lower or any item of 5th level or lower.",
