      "description": "A mix of digestive juices and green dragon poison glands nauseates the victim as its flesh is digested from within.\nActivate A Interact (Contact)\nSaving Throw check (fortitude, dc:37)\nOnset 1 minute\nMaximum Duration 6 rounds\nStage 1 6d6 poison damage and Sickened 2 (1 round)\nStage 2 7d6 poison damage and Sickened 3 (1 round)\nStage 3 9d6 poison damage and Sickened 4 (1 round)",
