      "itemType": "equipment",
      "level": 17,
      "rarity": "common",
      "traits": [
        "apex",
        "invested",
        "magical"
      ],
      "description": "This elegant silver band often resembles curling fig leaves and fits around your brow. You gain a +2 item bonus to Deception and Diplomacy checks. When you invest the circlet, you either increase your Charisma score by 2 or increase it to 18, whichever would give you a higher score.\nActivate 2 envision\nFrequency once per hour\nEffect You cast a 4th-rank Charm spell (DC 38).",
      "bulk": 0,
