      "description": "Usage affixed to one undead creature\nDuration 1 round\nThis classic fulu seals the void energy within an undead, freezing it in its tracks. Upon affixing, the target undead must attempt a check (will, dc:17, name:spirit-sealing fulu, showDC:all) save or be Paralyzed for 1 round.",
