      "level": 4,
      "rarity": "common",
      "traits": [
        "catalyst",
        "consumable",
        "magical"
      ],
      "description": "Activate Cast a Spell\nWhen energy courses through these lustrous beads, they glow brightly in the sacred colors of the spellcaster's faith. A Spiritual Weapon empowered with this catalyst flashes with bright light when it critically Strikes a target, causing the target to be Dazzled until the beginning of your next turn. The rosary can be used with a spiritual weapon of 4th level or below.\nEffect: Dazzling Rosary",
