      "name": "Thunderbird Tuft (Moderate)",
      "itemType": "consumable",
      "level": 5,
      "rarity": "common",
      "traits": [
        "catalyst",
        "consumable",
        "magical"
      ],
      "description": "Activate Cast a Spell (add 1 action)\nThis carved chunk of amber contains a single tuft of gray feathers, which spark with electricity to create an odd jittery sensation in anyone holding the amber for long. When used as part of a Shocking Grasp spell, thunderbird tuft funnels electricity back into the spellcaster in a defensive nimbus. For 1 minute, any creature that touches you or that hits you with a melee unarmed attack or non-reach melee weapon attack takes 1d4 electricity damage, or 1d6 electricity damage if the creature is using a metal weapon.",
