      "name": "Firestarter Pellets",
      "itemType": "consumable",
      "level": 5,
      "rarity": "common",
      "traits": [
        "catalyst",
        "consumable",
        "magical"
      ],
      "description": "Activate Cast a Spell (add 1 action)\nThese compacted pellets of bat guano, sulfur, and magical accelerants have long been a staple for spellcasters on the battlefield. Adding a firestarter pellet to a Fireball spell produces clinging flames that deal 1d6 persistent fire damage to all who fail the saving throw against the effect 2d6 persistent fire damage on a critical failure).",
