      "level": 6,
      "rarity": "common",
      "traits": [
        "consumable",
        "fulu",
        "magical",
        "talisman"
      ],
      "description": "Usage affixed to a weapon\nActivate f envision\nTrigger You successfully Strike an incorporeal creature with the weapon to which the fulu is affixed, but you haven't rolled damage.\nThis white paper fulu bears red ink and attunes a weapon to the spiritual essence of an incorporeal creature. Upon activation, the weapon gains the benefit of the ghost touch property rune against the triggering incorporeal creature for 1 minute.\nEffect: Ghostbane Fulu",
      "bulk": 0,
