      "itemType": "equipment",
      "level": 8,
      "rarity": "common",
      "traits": [
        "grimoire",
        "magical"
      ],
      "description": "When opening the book, whispers can be heard on the wind, or laughter rings in the distance.\nActivate f envision\nFrequency once per day\nTrigger You cast an enchantment spell prepared from this grimoire that has no effect because all targets critically succeeded on their saving throws\nEffect You quickly divert the failed enchantment energy into yourself to retain your favored spell in place of another. You lose another spell you prepared of an equal or higher level to the triggering enchantment spell but retain the ability to cast the enchantment spell again.",
