      "name": "Noxious Incense",
      "itemType": "consumable",
      "level": 9,
      "rarity": "common",
      "traits": [
        "catalyst",
        "consumable",
        "magical"
      ],
      "description": "Activate Cast a Spell\nSold only in single sticks, this foul incense comes coated with a bevy of alchemical smoke that activates in the presence of intense heat, releasing its namesake pungent odor. Adding this catalyst to a Wall of Fire spell fills all squares adjacent to the wall with thick, foul smoke. Creatures in this area are Concealed, and other creatures are concealed to creatures in the area. The smoke lasts for the duration of the spell. The incense can be used with a wall of fire of 6th level or below.",
      "bulk": 0.1,
