    "sourceHash": "sha256:bebca77dfc9370df947c77aa49995de16b4f148cebdafaf72ef6f6f30bc1b715",
    "translatableHash": "sha256:620924cf0f095268427f9a8cc128cc1cd7852c78582dd54c5e108188b882f3b1",
