      "name": "Retrieval Prism (Greater)",
      "itemType": "consumable",
      "level": 10,
      "rarity": "common",
      "traits": [
        "consumable",
        "magical",
        "talisman",
        "teleportation"
      ],
      "description": "Usage affixed to armor\nActivate f command\nRequirements You have a free hand.\nThis triangular prism showing swirling black patterns inside constantly moves around on your armor, no matter where you affix it. When you activate this talisman, any item in your possession of 1 bulk or less, chosen when you activate the prism, immediately teleports into your hand.\nThe retrieval prism can't retrieve an item that's not on your plane, including one that's in an extradimensional space like a bag of holding.",
      "bulk": 0,
      "price": {
        "gp": 200
      },
      "usage": "affixed-to-armor",
      "category": "talisman",
