    "sourceHash": "sha256:5a50dadec42bc2c72b47c147a90d492fc1519d692015d4c2a4eb67d8ad493cdb",
    "translatableHash": "sha256:94576e999d3b20c6e713c1902662e609d05e549d766175f9da11d24d85b73daf",
    "data": {
      "schemaVersion": 1,
      "name": "Buzzsaw Axe",
      "itemType": "weapon",
      "level": 11,
      "rarity": "common",
      "traits": [
        "magical",
        "sweep"
      ],
      "description": "With an aerodynamic cutting edge and a curved handle, this +2 striking battle axe is perfectly suited to whirling motions, and in fact seems like it wants to whirl free from your grip. A Strike with this axe that benefits from the sweep trait's circumstance bonus on attack rolls also gains a +2 circumstance bonus to the damage roll.\nActivate 2 command, Interact\nFrequency once per hour\nEffect You hurl the axe, which spins at great speed as it flies to a distant point and returns to you, leaving a trail of carnage. Each creature in a 120-foot line must succeed at a check (reflex, dc:28, basic, name:Thrown Buzzsaw Axe, traits:axe, showDC:all) save or take damage equal to the weapon's melee damage, including your Strength modifier.",
      "bulk": 0,
      "price": {
        "gp": 1400
      },
      "usage": "held-in-one-hand",
      "category": "martial",
      "group": "axe",
      "damage": {
        "dice": 1,
        "die": "d8",
        "type": "slashing"
      }
    }
