      "itemType": "equipment",
      "level": 12,
      "rarity": "common",
      "traits": [
        "earth",
        "magical",
        "spellheart"
      ],
      "description": "The crystal chamber within this split geode is divided into three lobes of equal size. The spell DC of any spell cast by Activating this item is 29.\n• Armor After you cast an earth spell by Activating the geode, you gain resistance 5 to physical damage (except adamantine) until the end of your next turn, or double the resistance for a non-cantrip spell.\n• Weapon After you cast an earth spell by Activating the geode, your Strikes with the weapon deal an additional 1d8 bludgeoning damage until the end of your next turn.\nEffect: Trinity Geode - Armor\nEffect: Trinity Geode - Weapon\nActivate Cast a Spell\nEffect You cast Scatter Scree.\nActivate Cast a Spell\nFrequency once per day\nEffect You cast 4th-rank One with Stone.\nActivate Cast a Spell\nFrequency once per day\nEffect You cast Spike Stones.",
