      "itemType": "weapon",
      "level": 12,
      "rarity": "common",
      "traits": [
        "magical",
        "staff",
        "two-hand-d8"
      ],
      "description": "This crooked staff is made from twisting acacia wood and has a sphere of rough sandstone embedded in the top, to channel the magic of the desert. When wielding this staff in deserts, you gain a +1 circumstance bonus to Survival checks to Subsist, Track, and Cover Tracks.\nActivate Cast a Spell\nEffect You expend a number of charges from the staff to cast a spell from the staff's list.\n• Cantrip Know the Way\n• 1st Create Water, Vanishing Tracks\n• 2nd Environmental Endurance, Enhance Victuals\n• 3rd Cleanse Affliction, Wall of Wind\n• 4th Air Walk\n• 5th Elemental Form\nCraft Requirements Supply one casting of all listed levels of all listed spells",
