      "level": 12,
      "rarity": "common",
      "traits": [
        "consumable",
        "fire",
        "magical",
        "potion"
      ],
      "description": "Activate 1 Interact\nOnce you ingest this strongly spiced, glowing red potion, blazing wings of a phoenix sprout from your back and carry you through the air. For 1 minute, you gain a Fly speed of 40 feet. The first time each round that you Fly (including to hover in place), you shed burning feathers that deal 3d4 fire damage to all creatures in a 10-foot emanation at the end of your movement (check (reflex, dc:29, basic, name:Phoenix Flask Fire Feathers, showDC:all, options:area-effect) save).\nEffect: Phoenix Flask",
