      "description": "A sheen of red crosses the surface of this star-shaped goldstone medallion when the light hits it. The affixed armor or weapon is warm to the touch. The spell attack roll of any spell cast by Activating this item is 1d20+19, and the spell DC is 29.\n• Armor You gain resistance 10 to fire.\n• Weapon After you cast a fire spell by Activating the star, your Strikes with the weapon deal an additional 1d8 fire damage until the end of your next turn.\nEffect: Flaming Star - Armor\nEffect: Flaming Star - Weapon\nActivate Cast a Spell\nEffect You cast Ignition.\nActivate Cast a Spell\nFrequency once per day\nEffect You cast 4th-rank Fireball.\ncheck (reflex, dc:29, basic, name:Flaming Star Spell, traits:spell, showDC:all)\nActivate Cast a Spell\nFrequency once per day\nEffect You cast Wall of Fire.",
