    "data": {
      "schemaVersion": 1,
      "name": "Invisible Chain Shirt",
      "itemType": "armor",
      "level": 13,
      "rarity": "common",
      "traits": [
        "comfort",
        "flexible",
        "magical"
      ],
      "description": "This +2 resilient Invisibility chain shirt is itself invisible. Other creatures can't see it at all, allowing you to wear it surreptitiously. Additionally, the armor's invisible composition is quieter and more comfortable than a normal chain shirt. It loses the noisy trait and gains the comfort trait.\nActivate 2 envision\nFrequency once per minute\nEffect You Stride and turn partially invisible, becoming Concealed until the end of your next turn or until you use a hostile action, whichever comes first. As normal, you can use the concealment from this activation to Hide.",
      "bulk": 1,
      "price": {
        "gp": 2750
      },
      "usage": "",
      "category": "light",
      "group": "chain",
      "armor": {
        "armorClassBonus": 2,
        "dexterityCap": 3,
        "checkPenalty": -1,
        "speedPenaltyFeet": 0
      }
    }
