      "name": "Force Tiles",
      "itemType": "consumable",
      "level": 13,
      "rarity": "common",
      "traits": [
        "catalyst",
        "consumable",
        "magical"
      ],
      "description": "Activate Cast a Spell\nLight refracts in strange ways through these precisely ground glass tiles, lengthening the refracted force and causing it to push back. Adding this catalyst to a Wall of Force spell increases the wall's maximum length to 80 feet and maximum height to 40 feet and causes creatures that try to move into the wall's space (or are Shoved into the wall) to take 2d6 force damage.",
