    "translatableHash": "sha256:7b0fe2d59641d2c3e1dfb5fe6b4773b28d46495f2d1169c40cd2b753c01bc977",
    "data": {
      "schemaVersion": 1,
      "name": "Stormbreaker Fulu",
      "itemType": "consumable",
      "level": 16,
      "rarity": "uncommon",
      "traits": [
        "consumable",
        "fulu",
        "magical",
        "talisman"
      ],
      "description": "Usage affixed to armor\nActivate f command\nTrigger You would be forced to move, you would be teleported, or you would take cold, electricity, or sonic damage.\nThis unassuming paper tag is inscribed with magical symbols. When you activate the fulu, it vanishes in a wisp of cloud, and you gain resistance 15 to cold, electricity, and sonic damage until the end of your next turn. For that duration, you ignore difficult terrain from wind and weather, and you can't be forcibly moved or teleported unless the effect counteracts the fulu (DC 40). These protections apply against the triggering effect.\nEffect: Stormbreaker Fulu",
      "bulk": 0,
      "price": {
        "gp": 1900
      },
      "usage": "affixed-to-armor",
      "category": "fulu",
      "group": "consumable"
    }
