      "traits": [
        "force",
        "magical"
      ],
      "description": "This rune thrums with pure magical energy. Weapons with the rune deal an additional 1d6 force damage on a successful Strike. On a critical hit, you can choose to force the target to succeed at a check (fortitude, dc:37, name:Resist Force Push, showDC:all) save or be pushed 10 feet away from you.",
