      "description": "The flayleaf plant is relatively common, though the mildly euphoric effects of smoking its dried leaves increase when it's sourced from plants specifically grown to produce such effects.\nActivate A Interact (Ingested, Inhaled)\nSaving Throw check (fortitude, dc:12)\nOnset 10 minutes\nMaximum Duration 4 hours\nStage 1 +1 item bonus to saving throws against mental effects (1 hour)\nStage 2 Fatigued and +1 item bonus to saving throws against mental effects (1 hour)\nStage 3 fatigued and Stupefied 1 (1 hour)\nStage 4 fatigued, Frightened 2, Stupefied 2 (1 hour)",
