      "name": "Heartstone",
      "itemType": "equipment",
      "level": 9,
      "rarity": "common",
      "traits": [
        "invested",
        "occult"
      ],
      "description": "This gemstone grants its wearer a +2 item bonus to saving throws.\nEach heartstone is powered by the spirit of a specific night hag. If it's separated from her for 24 hours (or she's been dead for 24 hours), it becomes a nonmagical gemstone. A heartstone allows the hag to use additional occult innate spells: Ethereal Jaunt (9th level) and Seize Soul at will, and Shadow Blast twice per day.\nActivate 1 command\nRequirements You must be touching the heartstone.\nEffect The heartstone attempts to counteract one disease affecting you (counteract rank 5, counteract modifier ).\nCraft Requirements You must be a night hag.",
