    "sourceHash": "sha256:13a65a4b0999c238cab3afa8264fc222ce185c4e9b98aaa33396447d61c23c37",
    "translatableHash": "sha256:9e6897529fea3346d8603b21197347c6be3394b27fdfd815c0493964f7830944",
    "data": {
      "schemaVersion": 1,
      "name": "Lich Soul Cage",
      "itemType": "equipment",
      "level": 12,
      "rarity": "rare",
      "traits": [
        "arcane",
        "void"
      ],
      "description": "This item is crafted by a spellcaster who wishes to become a lich. When a lich is destroyed, its soul flees to the soul cage. The phylactery then rebuilds the lich's undead body over the course of 1d10. Afterward, the lich manifests next to the soul cage, fully healed and in a new body (therefore, it lacks any equipment it had on its old body). A lich's soul cage must be destroyed to prevent a lich from returning.\nThe standard soul cage is a sealed metal box containing strips of parchment inscribed with magical phrases. This box has Hardness 9 and 36 HP, but some liches devise more durable or difficult-to-obtain soul cages. A soul cage might also come in the form of a ring, an amulet, or a similar item; the specifics are up to the creator.",
      "bulk": 0,
      "price": {
        "gp": 1600
      },
      "usage": "held-in-one-hand",
      "category": "equipment",
      "group": "equipment"
    }
