      "description": "Activate 1 Interact\nThis mirrored bottle contains various chemicals dissolved in two immiscible solvents. Shaking the bottle induces chemical reactions that cause it to glow. For 1 hour, the bottle sheds bright light in a 20-foot radius (and dim light to the next 40 feet).\nDuring this hour, it can be thrown like a bomb. This requires a single action to Activate with a Strike, like other bombs, and deals the damage below. If it's not thrown within an hour of the first activation, it defuses harmlessly and is consumed.\nThe bomb deals 2d4 vitality damage and 2 vitality splash damage, as well as 2d4 additional fire damage. As normal, vitality damage harms only undead and other creatures with void healing. Undead with a particular vulnerability to sunlight (such as vampires or wraiths) take the maximum amount of vitality damage from bottled sunlight 8 vitality damage instead of 2d4). For any ability that depends on the number of weapon dice bottled sunlight has, count only the vitality damage dice.",
