      "description": "This shining symbol of Sarenrae depicts the goddess with her arms held wide. In the center of the symbol is a crystal reliquary with a perfect feather floating inside, glowing bright as a candle with the light of the goddess.\nActivate Cast a Spell\nFrequency once per day for each spell\nEffect The dawnlight casts 5th-rank Vitality Lash or Light, or 4th-rank Holy Light or Vital Beacon. The dawnlight's spell attack roll and counteract modifier are +18, and any spell with the light trait is treated as though its counteract rank were 1 higher for counteracting darkness.\nWhenever you successfully counteract magical darkness while holding this symbol, the clash of magic unleashes a momentary flash of light. Creatures with darkvision in the area of the light spell or targeted by it must succeed at a check (fortitude, dc:28) or be Dazzled for 1 round. Those with light blindness are also exposed to bright light.\nCraft Requirements You have a spellcasting class feature with the divine tradition.",
