      "name": "Retaliation (Lesser)",
      "itemType": "equipment",
      "level": 6,
      "rarity": "common",
      "traits": [
        "magical"
      ],
      "description": "Shields with a retaliation rune use the impact of weapons to generate blasts of explosive force that counterattack foes.\nActivate F envision\nFrequency once per hour\nTrigger You Shield Block a melee Strike\nEffect You unleash force damage against the creature that made the triggering attack. This attack deals 4d4 force damage (check (reflex, dc:20, basic)).",
