      "rarity": "common",
      "traits": [
        "alchemical",
        "consumable",
        "drug",
        "ingested",
        "inhaled",
        "poison"
      ],
      "description": "When eaten or smoked, pesh gives users a sense of well-being, sometimes with hallucinations, aggression, and exhaustion.\nActivate A Interact (Ingested, Inhaled)\nSaving Throw check (fortitude, dc:12)\nOnset 1 minute\nMaximum Duration 6 hours\nStage 1 Stupefied 1 and a +2 item bonus to saves versus fear effects (1 minute)\nStage 2 1 temporary Hit Point per level (first time you reach this stage only), +2 item bonus to saves versus fear effects, Clumsy 1, and stupefied 1 (1 minute)\nStage 3 Clumsy 2 and Stupefied 2 (1 hour)",
