      "itemType": "equipment",
      "level": 3,
      "rarity": "uncommon",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "These gleaming golden epaulets are issued to Eagle Knight officers and worn as part of the uniform. While they can be enchanted to provide a variety of effects, the Golden Legion epaulet remains the most common.\nActivate A (Command)\nFrequency once per day\nEffect Issue an order as part of the command. You and each ally within 60 feet who follows that order gain a +1 status bonus to attack rolls, damage rolls, and saving throws against fear until the beginning of your next turn.\nEffect: Golden Legion Epaulet",
